DECLARE mapping jsonb := '[{"id":"caeb376d-0a7d-5bf7-b18a-68c82557b61d","source_session_id":"craig-AdabEqbzngmT-stage1-full","old_cover":"https://raw.githubusercontent.com/Faysk/dnd-scribe/48f8a43e8145e782d3bf4186a4a9b4218a92c643/web/assets/sessions/2026-06-24/card.webp","new_cover":"https://dnd.faysk.dev/assets/sessions/2026-06-24/card.webp","old_hero":"https://raw.githubusercontent.com/Faysk/dnd-scribe/48f8a43e8145e782d3bf4186a4a9b4218a92c643/web/assets/sessions/2026-06-24/hero.webp","new_hero":"https://dnd.faysk.dev/assets/sessions/2026-06-24/hero.webp"},{"id":"7cf2c458-2b61-4384-8fb4-b430ff6c56c9","source_session_id":"craig-BIRq3nIWB4v9","old_cover":"https://raw.githubusercontent.com/Faysk/dnd-scribe/48f8a43e8145e782d3bf4186a4a9b4218a92c643/web/assets/sessions/2026-06-27/card.webp","new_cover":"https://dnd.faysk.dev/assets/sessions/2026-06-27/card.webp","old_hero":"https://raw.githubusercontent.com/Faysk/dnd-scribe/48f8a43e8145e782d3bf4186a4a9b4218a92c643/web/assets/sessions/2026-06-27/hero.webp","new_hero":"https://dnd.faysk.dev/assets/sessions/2026-06-27/hero.webp"},{"id":"abc4ef3c-ddb3-42e5-94d6-023fbab579e8","source_session_id":"manual-2026-07-01-20260701-sessao-235100","old_cover":"https://raw.githubusercontent.com/Faysk/dnd-scribe/48f8a43e8145e782d3bf4186a4a9b4218a92c643/web/assets/sessions/2026-07-01/card.webp","new_cover":"https://dnd.faysk.dev/assets/sessions/2026-07-01/card.webp","old_hero":"https://raw.githubusercontent.com/Faysk/dnd-scribe/48f8a43e8145e782d3bf4186a4a9b4218a92c643/web/assets/sessions/2026-07-01/hero.webp","new_hero":"https://dnd.faysk.dev/assets/sessions/2026-07-01/hero.webp"},{"id":"7cb15987-8493-4f37-8eae-92c7d6d46a07","source_session_id":"manual-2026-07-05-20260705-sessao-000806","old_cover":"https://raw.githubusercontent.com/Faysk/dnd-scribe/48f8a43e8145e782d3bf4186a4a9b4218a92c643/web/assets/sessions/2026-07-04/card.webp","new_cover":"https://dnd.faysk.dev/assets/sessions/2026-07-04/card.webp","old_hero":"https://raw.githubusercontent.com/Faysk/dnd-scribe/48f8a43e8145e782d3bf4186a4a9b4218a92c643/web/assets/sessions/2026-07-04/hero.webp","new_hero":"https://dnd.faysk.dev/assets/sessions/2026-07-04/hero.webp"},{"id":"c45bf33a-3e00-4c67-a162-5b17b6b0d36c","source_session_id":"fqSsIl6c2HeV","old_cover":"https://raw.githubusercontent.com/Faysk/dnd-scribe/48f8a43e8145e782d3bf4186a4a9b4218a92c643/web/assets/sessions/2026-07-11/card.webp","new_cover":"https://dnd.faysk.dev/assets/sessions/2026-07-11/card.webp","old_hero":"https://raw.githubusercontent.com/Faysk/dnd-scribe/48f8a43e8145e782d3bf4186a4a9b4218a92c643/web/assets/sessions/2026-07-11/hero.webp","new_hero":"https://dnd.faysk.dev/assets/sessions/2026-07-11/hero.webp"},{"id":"fbbbf955-bdd0-47ad-bdea-f8e6f6a93891","source_session_id":"AY2M6WBqKgq9","old_cover":"https://raw.githubusercontent.com/Faysk/dnd-scribe/48f8a43e8145e782d3bf4186a4a9b4218a92c643/web/assets/sessions/2026-07-25/card.webp","new_cover":"https://dnd.faysk.dev/assets/sessions/2026-07-25/card.webp","old_hero":"https://raw.githubusercontent.com/Faysk/dnd-scribe/48f8a43e8145e782d3bf4186a4a9b4218a92c643/web/assets/sessions/2026-07-25/hero.webp","new_hero":"https://dnd.faysk.dev/assets/sessions/2026-07-25/hero.webp"}]'::jsonb; item jsonb; current_row public.sessions%rowtype; count_changed integer := 0; snapshot jsonb; actual jsonb;
BEGIN
 SELECT jsonb_agg(jsonb_build_object('id',s.id,'other_columns_hash',md5((to_jsonb(s)-'metadata')::text),'other_metadata_hash',md5((s.metadata-'coverImageUrl'-'heroImageUrl')::text)) ORDER BY s.id) INTO snapshot FROM public.sessions s JOIN public.campaigns c ON c.id=s.campaign_id WHERE c.slug='yuhara-main' AND s.status='published';
 IF jsonb_array_length(snapshot) <> 11 THEN RAISE EXCEPTION 'session inventory changed'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(mapping) LOOP
 SELECT s.* INTO STRICT current_row FROM public.sessions s JOIN public.campaigns c ON c.id=s.campaign_id WHERE s.id=(item->>'id')::uuid AND s.source_session_id=item->>'source_session_id' AND s.status='published' AND c.slug='yuhara-main' FOR UPDATE OF s;
 IF current_row.metadata->>'coverImageUrl' IS DISTINCT FROM item->>'old_cover' OR current_row.metadata->>'heroImageUrl' IS DISTINCT FROM item->>'old_hero' THEN RAISE EXCEPTION 'media compare-and-swap mismatch'; END IF;
 UPDATE public.sessions SET metadata=metadata||jsonb_build_object('coverImageUrl',item->>'new_cover','heroImageUrl',item->>'new_hero') WHERE id=current_row.id AND metadata->>'coverImageUrl'=item->>'old_cover' AND metadata->>'heroImageUrl'=item->>'old_hero';
 IF NOT FOUND THEN RAISE EXCEPTION 'media update missing'; END IF;
 count_changed := count_changed+1;
 END LOOP;
 IF count_changed <> 6 THEN RAISE EXCEPTION 'unexpected update count'; END IF;
 SELECT jsonb_agg(jsonb_build_object('id',s.id,'other_columns_hash',md5((to_jsonb(s)-'metadata')::text),'other_metadata_hash',md5((s.metadata-'coverImageUrl'-'heroImageUrl')::text)) ORDER BY s.id) INTO actual FROM public.sessions s JOIN public.campaigns c ON c.id=s.campaign_id WHERE c.slug='yuhara-main' AND s.status='published';
 IF actual IS DISTINCT FROM snapshot THEN RAISE EXCEPTION 'unrelated fields changed'; END IF;
END $repair$;
COMMIT;
SELECT id, source_session_id, metadata->>'coverImageUrl' as cover, metadata->>'heroImageUrl' as hero FROM public.sessions WHERE id IN ('caeb376d-0a7d-5bf7-b18a-68c82557b61d'::uuid,'7cf2c458-2b61-4384-8fb4-b430ff6c56c9'::uuid,'abc4ef3c-ddb3-42e5-94d6-023fbab579e8'::uuid,'7cb15987-8493-4f37-8eae-92c7d6d46a07'::uuid,'c45bf33a-3e00-4c67-a162-5b17b6b0d36c'::uuid,'fbbbf955-bdd0-47ad-bdea-f8e6f6a93891'::uuid) ORDER BY id;
